from math import lcm


def cycles(perm):
    seen, out = set(), []
    for start in range(len(perm)):
        if start in seen:
            continue
        c, k = [], start
        while k not in seen:
            seen.add(k)
            c.append(k)
            k = perm[k]
        if len(c) > 1:
            out.append(c)
    return out


def perm_order(perm):
    return lcm(*[len(c) for c in cycles(perm)], 1)
